Chronostratigraphy.queryBreadcrumbs:
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX ex: <${prefix}/Chronostratigraphy/>

SELECT ?narrowerConcept
WHERE {
  ex:${term} skos:broader+ ?narrowerConcept.
}

Chronostratigraphy.queryVocabolo:
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX ex: <${prefix}/Chronostratigraphy/>

SELECT ?predicate ?object
WHERE {
  ex:${term} ?predicate ?object .
}

